<?php require_once __DIR__.'/../inc/functions.php';require_login();$search=trim($_GET['q']??'');$page=max(1,(int)($_GET['page']??1));$perPage=10;$where='';$params=[];if($search!==''){$where=' WHERE name LIKE ? OR email LIKE ? OR phone LIKE ?';$like='%'.$search.'%';$params=[$like,$like,$like];}$count=db()->prepare('SELECT COUNT(*) FROM students'.$where);$count->execute($params);$total=(int)$count->fetchColumn();$pages=max(1,(int)ceil($total/$perPage));$page=min($page,$pages);$offset=($page-1)*$perPage;$stmt=db()->prepare('SELECT * FROM students'.$where.' ORDER BY created_at DESC,id DESC LIMIT '.$perPage.' OFFSET '.$offset);$stmt->execute($params);$students=$stmt->fetchAll();$title='قائمة الطلاب';require __DIR__.'/../inc/header.php'; ?>
<div class="page-heading d-flex flex-wrap justify-content-between align-items-center gap-3 mb-4"><div><span class="eyebrow">إدارة السجلات</span><h1 class="h3 mb-1">قائمة الطلاب</h1><p class="text-muted mb-0">استعرض بيانات الطلاب وابحث عنها أو حدّثها بسهولة.</p></div><a class="btn btn-primary" href="<?=BASE_URL?>/students/add.php">+ إضافة طالب</a></div><form class="search-panel row g-2 mb-3" method="get"><div class="col-sm-9"><input class="form-control" name="q" value="<?=e($search)?>" placeholder="ابحث بالاسم أو البريد الإلكتروني أو الهاتف"></div><div class="col-sm-3 d-grid"><button class="btn btn-outline-primary">بحث</button></div><?php if($search!==''): ?><div><a href="<?=BASE_URL?>/students/index.php">مسح البحث</a></div><?php endif; ?></form><div class="directory-card"><div class="table-responsive"><table class="table table-hover align-middle mb-0"><thead class="table-light"><tr><th>#</th><th>الصورة</th><th>الاسم</th><th>البريد الإلكتروني</th><th>الهاتف</th><th>العنوان</th><th>الإجراءات</th></tr></thead><tbody><?php if(!$students): ?><tr><td colspan="7" class="text-center py-4">لا توجد سجلات مطابقة.</td></tr><?php endif; ?><?php foreach($students as $s): ?><tr><td><?= (int)$s['id']?></td><td><?php if($s['profile_picture']): ?><img class="avatar" src="<?=BASE_URL?>/uploads/<?=e($s['profile_picture'])?>" alt="صورة"><?php else: ?><span class="avatar-placeholder">—</span><?php endif; ?></td><td><?=e($s['name'])?></td><td><?=e($s['email'])?></td><td><?=e($s['phone'])?></td><td class="address-cell"><?=e($s['address'])?></td><td class="text-nowrap"><a class="btn btn-sm btn-outline-primary" href="<?=BASE_URL?>/students/edit.php?id=<?=(int)$s['id']?>">تعديل</a> <form class="d-inline" method="post" action="<?=BASE_URL?>/students/delete.php" data-confirm="هل أنت متأكد من حذف هذا الطالب؟ لا يمكن التراجع عن الحذف."><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=(int)$s['id']?>"><button class="btn btn-sm btn-outline-danger">حذف</button></form></td></tr><?php endforeach; ?></tbody></table></div></div><div class="directory-meta d-flex flex-wrap justify-content-between align-items-center mt-3"><span>عدد النتائج: <?=$total?> — الصفحة <?=$page?> من <?=$pages?></span><nav aria-label="ترقيم الصفحات"><ul class="pagination mb-0"><?php $base='?q='.urlencode($search).'&page='; ?><li class="page-item <?=$page<=1?'disabled':''?>"><a class="page-link" href="<?=$base.max(1,$page-1)?>">السابق</a></li><?php for($i=max(1,$page-2);$i<=min($pages,$page+2);$i++): ?><li class="page-item <?=$i===$page?'active':''?>"><a class="page-link" href="<?=$base.$i?>"><?=$i?></a></li><?php endfor; ?><li class="page-item <?=$page>=$pages?'disabled':''?>"><a class="page-link" href="<?=$base.min($pages,$page+1)?>">التالي</a></li></ul></nav></div><?php require __DIR__.'/../inc/footer.php'; ?>